BEGIN;
CREATE SEQUENCE salary_number_seq;
CREATE TABLE staff_salaries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),salary_number varchar(80) NOT NULL UNIQUE,staff_user_id uuid NOT NULL REFERENCES app_users(id),staff_name varchar(160) NOT NULL,staff_role varchar(16) NOT NULL CHECK(staff_role IN('admin','staff')),salary_month char(7) NOT NULL CHECK(salary_month ~ '^\d{4}-\d{2}$'),gross_paise bigint NOT NULL CHECK(gross_paise>0),calendar_days integer NOT NULL CHECK(calendar_days BETWEEN 28 AND 31),absent_days numeric(4,1) NOT NULL DEFAULT 0 CHECK(absent_days>=0),advance_paise bigint NOT NULL DEFAULT 0 CHECK(advance_paise>=0),net_paise bigint NOT NULL CHECK(net_paise>=0),paid_paise bigint NOT NULL DEFAULT 0 CHECK(paid_paise>=0 AND paid_paise<=net_paise),payment_date date NOT NULL,payment_mode varchar(40) NOT NULL,notes varchar(500),status varchar(16) NOT NULL CHECK(status IN('pending','partial','paid','void')),version integer NOT NULL DEFAULT 1 CHECK(version>=1),created_by uuid REFERENCES app_users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),voided_at timestamptz);
CREATE INDEX staff_salary_month_idx ON staff_salaries(salary_month DESC,salary_number DESC);
CREATE INDEX staff_salary_user_idx ON staff_salaries(staff_user_id,salary_month DESC);
CREATE TABLE staff_salary_revisions(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,salary_id uuid NOT NULL REFERENCES staff_salaries(id),version integer NOT NULL,previous_record jsonb NOT NULL,changed_by uuid REFERENCES app_users(id),changed_at timestamptz NOT NULL DEFAULT now());
COMMIT;
